\"::FLOAT AS TAX_2, i.value:\"Tax_3\"::FLOAT AS TAX_3, i.value:\"Tax_Amt_1\"::FLOAT AS TAX_AMT_1, i.value:\"Tax_Amt_2\"::FLOAT AS TAX_AMT_2, i.value:\"Tax_Amt_3\"::FLOAT AS TAX_AMT_3, i.value:\"Weight\"::FLOAT AS WEIGHT FROM snitch_db.maplemonk.logicstream_get_stock_transfer_out h, LATERAL FLATTEN(input => h.LSTITEMS) i ) SELECT * FROM final_stock_transfer_out_lines; create or replace table snitch_db.maplemonk.logic_final_sti as SELECT BILL_NO, DOC_TYPE, QUANTITY AS TOTAL_QUANTITY, VOUCH_NO, TRY_TO_DATE(BILL_DATE, \'DD/MM/YYYY\') AS BILL_DATE, TOTAL_TAX, AGENT_NAME, GRN_NUMBER, GRN_PREFIX, NET_AMOUNT, VOUCH_CODE, TRY_TO_DATE(VOUCH_DATE, \'DD/MM/YYYY\') AS VOUCH_DATE, ACTION_CODE, BRANCH_CODE, BRANCH_NAME, ACCOUNT_CODE, ACCOUNT_NAME, GROSS_AMOUNT, CURRENCY_NAME, DOC_TYPE_DESC, TAX_REGION_NAME, LISTITEMS.value:AddlItemCode::STRING AS SKU, LISTITEMS.value:CD::NUMBER AS CD, LISTITEMS.value:CD_Per::NUMBER AS CD_Per, LISTITEMS.value:CF_1::NUMBER AS CF_1, LISTITEMS.value:CF_2::NUMBER AS CF_2, LISTITEMS.value:CF_3::NUMBER AS CF_3, LISTITEMS.value:Gross_Pur_Amt::NUMBER AS Gross_Pur_Amt, LISTITEMS.value:HSN_Code::STRING AS HSN_Code, LISTITEMS.value:ItemCode::STRING AS ItemCode, LISTITEMS.value:Item_MRP::NUMBER AS Item_MRP, LISTITEMS.value:Item_Pur_Rate::NUMBER AS Item_Pur_Rate, LISTITEMS.value:Item_Sale_Rate::NUMBER AS Item_Sale_Rate, LISTITEMS.value:Lot_Code::STRING AS Lot_Code, LISTITEMS.value:Lot_MRP::NUMBER AS Lot_MRP, LISTITEMS.value:Lot_Number::STRING AS Lot_Number, LISTITEMS.value:PackName::STRING AS PackName, LISTITEMS.value:Quantity::NUMBER AS Item_Quantity, LISTITEMS.value:Rate::NUMBER AS Item_Rate, LISTITEMS.value:Tax_Amt_1::NUMBER AS Tax_Amt_1, LISTITEMS.value:Tax_Amt_3::NUMBER AS Tax_Amt_3, LISTITEMS.value:Tax_P_1::NUMBER AS Tax_P_1, LISTITEMS.value:Tax_P_2::NUMBER AS Tax_P_2, LISTITEMS.value:Tax_P_3::NUMBER AS Tax_P_3 FROM snitch_db.maplemonk.logicstream_get_stock_transfer_in, LATERAL FLATTEN(INPUT => LISTITEMS) AS LISTITEMS; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING AS select distinct stock_transfer_branchname as store_name, city_name as region, state_name as cluster, stock_transfer_branchcode as store_code from snitch_db.maplemonk.logicERPnew_get_party_master ; CREATE OR REPLACE TABLE snitch_db.maplemonk.sto_analysis AS WITH final_sto_data AS ( SELECT CASE WHEN account_name LIKE \'%SLIKK%\' THEN \'SLIKK\' WHEN (branch_name LIKE \'%SNITCH - WH - YE%\' OR branch_name LIKE \'%SNITCH - WH - EM%\') AND (account_name NOT LIKE \'%YELHA%\' OR account_name NOT LIKE \'%EMIZA%\') THEN \'WH-STORE\' WHEN (account_name LIKE \'%SNITCH - WH - YE%\' OR account_name LIKE \'%SNITCH - WH - EM%\') AND (branch_name LIKE \'%CO%\' OR branch_name LIKE \'%FO%\') THEN \'STORE-WH\' WHEN (account_name LIKE \'%CO%\' OR account_name LIKE \'%FO%\') AND (branch_name LIKE \'%CO%\' OR branch_name LIKE \'%FO%\') THEN \'IST\' WHEN (account_name LIKE \'%SNITCH - WH - YE%\' OR account_name LIKE \'%SNITCH - WH - EM%\') AND (branch_name LIKE \'%WH%\') THEN \'STORE-WH\' ELSE \'OTHERS\' END AS ORIGIN, TO_DATE(bill_date, \'DD/MM/YYYY\') AS DATE, TO_TIMESTAMP(bill_time, \'DD/MM/YYYY HH12:MI AM\') as time, account_name AS to_party, branch_name AS from_party, item_quantity, bill_no, order_no, total_quantity, doc_number, net_amount, vouch_code, so_order_no, account_code, sku, item_group_name_1 AS category, item_mrp, lot_bill_no, lot_purchase_date FROM snitch_db.maplemonk.logic_final_sto WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT DISTINCT fsd.*, gs.store_name, gs.cluster, gs.region FROM final_sto_data fsd LEFT JOIN SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING gs ON fsd.from_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.sti_analysis AS WITH final_sti_data AS ( SELECT CASE WHEN BRANCH_NAME LIKE \'%SLIKK%\' THEN \'WH-SLIKK\' WHEN account_name LIKE \'%SNITCH - WH%\' AND (branch_name LIKE \'%SNITCH - WH - YE%\' OR branch_name LIKE \'%SNITCH - WH - EM%\') THEN \'WH-STORE\' WHEN branch_name LIKE \'%SNITCH - WH%\' AND (account_name LIKE \'%SNITCH - WH - YE%\' OR account_name LIKE \'%SNITCH - WH - EM%\') THEN \'STORE-WH\' WHEN branch_name LIKE \'%SNITCH - WH%\' AND account_name LIKE \'%SNITCH%\' THEN \'STORE-WH\' WHEN branch_name LIKE \'%SNITCH - WH%\' THEN \'NOTFOUND-WH\' WHEN (branch_name LIKE \'%COCO%\' OR branch_name LIKE \'%FOCO%\' OR branch_name LIKE \'%COFO%\' OR branch_name LIKE \'%JAYAN%\' OR branch_name LIKE \'%BRIG%\') AND account_name LIKE \'%SNITCH - WH -%\' THEN \'WH-STORE\' WHEN (branch_name LIKE \'%COCO%\' OR branch_name LIKE \'%FOCO%\' OR branch_name LIKE \'%COFO%\' OR branch_name LIKE \'%JAYAN%\' OR branch_name LIKE \'%BRIG%\') AND (account_name LIKE \'%COCO%\' OR account_name LIKE \'%FOCO%\' OR account_name LIKE \'%COFO%\' OR account_name LIKE \'%JAYAN%\' OR account_name LIKE \'%BRIG%\') THEN \'IST\' ELSE \'OTHERS\' END AS ORIGIN, bill_date AS DATE, account_name AS from_party, branch_name AS to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp FROM snitch_db.maplemonk.logic_final_sti WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT DISTINCT fsd.*, gs.store_name, gs.cluster, gs.region FROM final_sti_data fsd LEFT JOIN snitch_db.maplemonk.offline_store_detailed_mapping gs ON fsd.to_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.purchasev_analysis AS WITH final_purchasev_data AS ( SELECT CASE WHEN branch_name LIKE \'%SNITCH - WH%\' AND account_name LIKE \'%SNITCH%\' THEN \'STORE-WH\' WHEN branch_name LIKE \'%SNITCH - WH%\' THEN \'VENDOR-WH\' WHEN (branch_name LIKE \'%COCO%\' OR branch_name LIKE \'%FOCO%\' OR branch_name LIKE \'%COFO%\' OR branch_name LIKE \'%JAYAN%\' OR branch_name LIKE \'%BRIG%\') AND account_name LIKE \'%SNITCH - WH -%\' THEN \'WH-STORE\' ELSE \'OTHERS\' END AS ORIGIN, bill_date AS DATE, account_name AS from_party, branch_name AS to_party, item_quantity, bill_no, quantity as total_quantity, net_amount, vouch_code, account_code, ADDLITEMCODE as sku, item_mrp FROM snitch_db.maplemonk.logic_purchase_voucher WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT DISTINCT fpd.*, gs.store_name, gs.cluster, gs.region FROM final_purchasev_data fpd LEFT JOIN snitch_db.maplemonk.offline_store_detailed_mapping gs ON fpd.to_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_store_inward AS WITH sti_data AS ( SELECT ORIGIN, DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp, store_name, cluster, region FROM snitch_db.maplemonk.sti_analysis ), purchasev_data AS ( SELECT ORIGIN, DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp, store_name, cluster, region FROM snitch_db.maplemonk.purchasev_analysis ) SELECT * FROM sti_data UNION ALL SELECT * FROM purchasev_data; CREATE OR REPLACE TABLE snitch_db.maplemonk.outward_accuracy AS WITH match1 AS ( SELECT TRY_TO_DATE(DATE, \'DD/MM/YYYY\') AS raised_date, type, store, uniquecode AS request_no, NULLIF(so_number, \'-\') AS Sale_NUMBER, quantity AS qty_raised, CONCAT(sale_number, store) AS match1 FROM snitch_db.maplemonk.gs_store_outward_tracker_store ), match2 AS ( SELECT bill_no, so_order_no, quantity AS qty_completed, try_to_date(bill_date,\'DD/MM/YYYY\') as bill_date, branch_name, CONCAT(SO_ORDER_NO, BRANCH_NAME) AS match2 FROM snitch_db.maplemonk.logicstream_get_stock_transfer_out WHERE branch_name LIKE \'%CO%\' OR branch_name LIKE \'%FO%\' ), final_combination AS ( SELECT m1.raised_date, m1.type, m1.store, m1.request_no, m1.Sale_NUMBER, m1.qty_raised, m2.bill_no, m2.so_order_no, m2.qty_completed, m2.bill_date, m2.branch_name, m1.qty_raised - m2.qty_completed AS miss_quantity FROM match1 m1 LEFT JOIN match2 m2 ON m1.match1 = m2.match2 ), final_data_with_store_details AS ( SELECT DISTINCT fc.*, sd.store_name, sd.cluster, sd.region FROM final_combination fc LEFT JOIN snitch_db.maplemonk.OFFLINE_STORE_DETAILED_MAPPING sd ON fc.store = sd.store_name ) SELECT * FROM final_data_with_store_details; ;",
                    "transaction": true
                }
            ) }}
